// CSD_RATIONALE_BEGIN
// Attempt 43 (52%) holds the best accuracy. The 141 semantic-mismatch failures share
// identifiable surface patterns visible in the rollout examples:
//   (a) Table-alias column prefixes: `c.lifeexpectancy`, `cl.isofficial` instead of bare names
//   (b) SELECT column aliases used in ORDER BY: `COUNT(*) AS cnt … ORDER BY cnt`
//   (c) Wrong query structure for negation: model uses JOIN+GROUP BY instead of NOT IN subquery
//   (d) Wrong query structure for frequency: GROUP BY clause missing or HAVING absent
//
// Root cause of the 33.7% regression in attempts 55-57:
//   – Removing IsCompletePrefix early-close (attempt 57) let the model emit garbage after a
//     valid SQL prefix (e.g. runaway LIMIT numbers, extraneous newlines), and
//     CloseSpanWithinBudget then closed on that garbage prefix.
//   – Adding a 150-step constrained cap caused EOS to fire after truncated queries.
//
// This attempt keeps the proven attempt-43 structural skeleton exactly:
//   Phase 1 – 5-step unconstrained preamble (emit "SQL: ")
//   Phase 2 – OpenConstrainedSpan if not already inside
//   Phase 3 – GroupBoostedConstrainedStep with IsCompletePrefix early-close
//   Phase 4 – CloseSpanWithinBudget(≤80) safety net
//
// The single change: a substantially more specific guidance string that directly
// addresses patterns (a)–(d) observed in the failing rollouts, reducing the model's
// tendency toward table-alias prefixes, AS aliases, and wrong query structure for
// negation/counting questions.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 preamble: Loop guard includes !insideConstrainedOut so the body runs
//   only while insideConstrainedOut is false (implication vacuously true). We set
//   insideConstrainedOut := true only via RenderedEndsWith, simultaneously assigning
//   currentConstrainedOut := [] which satisfies IsValidPrefix([]) by method precondition.
//   EOS breaks without changing insideConstrainedOut; invariant holds.
//
//   Phase 2 OpenConstrainedSpan: Only reached when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := [] and insideConstrainedOut := true; IsValidPrefix([]) holds.
//
//   Phase 3 main loop:
//     IsCompletePrefix branch: CloseConstrainedSpan requires IsCompletePrefix (which implies
//     IsValidPrefix) and sets insideConstrainedOut := false, making the implication vacuous,
//     and clears currentConstrainedOut := [].
//     Normal step branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus
//     EOS; the returned token is either EOS (no append) or valid next. AppendConstrainedToken
//     extends currentConstrainedOut by exactly one valid token, preserving IsValidPrefix by
//     the parser extension contract.
//     EOS path: we call CloseConstrainedSpan only under IsCompletePrefix guard; this sets
//     insideConstrainedOut := false.
//
//   Phase 4 CloseSpanWithinBudget: postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 otherwise); invariant preserved each iteration.
//   Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token;
//   net 1:1 token-to-step; invariant preserved.
//   Phase 3:
//     IsCompletePrefix branch: CloseConstrainedSpan costs +1 step and appends at most 1 ">>"
//     token (net ≤ 1 token per step); then break.
//     Normal branch: GroupBoostedConstrainedStep costs +1 step; on non-EOS,
//     AppendConstrainedToken appends exactly 1 token (net 1:1); on EOS, 0 tokens appended.
//     EOS+close sub-path: steps += 1 (EOS), then steps += 1 (CloseConstrainedSpan);
//     generated grows by at most 1 (the ">>" delimiter); invariant holds across both increments.
//   Phase 4: closeBudget := min(remaining, 80); CloseSpanWithinBudget postcondition gives
//   |generatedOut| <= |generated_before| + closeBudget; steps_after = steps_before + closeBudget;
//   therefore |generated| <= |generatedPrefix| + steps_after. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a SQL SELECT query. Output exactly: SQL: <<your_sql_query>> with the query between << and >>. STRICT RULES: (1) Never use table alias prefixes in column names. Write 'age' not 'e.age', write 'lifeexpectancy' not 'c.lifeexpectancy'. FROM clause may name a table but do NOT alias it with a short letter. (2) Never use AS aliases in SELECT expressions. Write 'COUNT(*)' not 'COUNT(*) AS cnt'. Write 'AVG(lifeexpectancy)' not 'AVG(lifeexpectancy) AS avg_life'. (3) ORDER BY the actual expression, not an alias. Write 'ORDER BY COUNT(*) DESC' not 'ORDER BY cnt DESC'. (4) For 'not X' / 'where Y is not the official Z' questions use: WHERE col NOT IN (SELECT col FROM table WHERE condition). Do NOT use a JOIN with a WHERE filter that only selects the excluded rows. (5) For 'more than N employees/items' questions use GROUP BY col HAVING COUNT(*) > N. (6) Use only exact table and column names from the provided schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with schema-token boosting.
// IsCompletePrefix gates closure so we do not emit ">>" on a partial parse.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget as safety net.
// This handles the rare case where the model reached EOS without a complete parse.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

